def factorial(number):
    if number <= 1:
        return 1
    return number * factorial(number - 1)
print(factorial(5))

def sum_to(number):
    if number <= 0:
        return 0
    return number + sum_to(number - 1)
print(sum_to(4))

def countdown(number):
    if number <= 0:
        return
    print(number)
    countdown(number - 1)

countdown(3)
